            ["NFR-02", "Tương thích", "API là REST/JSON nên cùng một backend phục vụ web và di động.", "axios ở cả hai ứng dụng, baseURL cấu hình qua biến môi trường."],
            ["NFR-03", "Hiệu năng", "Giới hạn 300 yêu cầu/phút cho mỗi IP trên /api; phân trang danh sách; chỉ số trên các cột truy vấn thường dùng.", "express-rate-limit; parsePagination; CREATE INDEX trong migration."],
            ["NFR-04", "Bảo mật", "Mật khẩu băm bcrypt; API quản trị yêu cầu JWT; header bảo vệ của helmet; CORS giới hạn origin; giới hạn kích thước body 2 MB và tệp tải lên 10 MB.", "bcryptjs, jsonwebtoken, helmet, cors, multer."],
