    ("h3", "1.2.3. Quy tắc nghiệp vụ"),
    ("p", "Bảng 1.4 phân biệt quy tắc đã được cài đặt trong mã nguồn và quy tắc mới ở mức thiết kế. Đây là điểm quan trọng: một quy tắc có bảng dữ liệu chưa chắc đã được thi hành ở tuyến nội dung."),
    ("tbl", {
        "caption": "Bảng 1.4. Quy tắc nghiệp vụ",
        "cols": ["Mã", "Quy tắc", "Cách thi hành", "Trạng thái"],
        "widths": [1.4, 8.4, 5.2, 2.0],
        "rows": [
            ["BR-01", "Mã QR của địa điểm trỏ tới /place/{id}; mã QR của món ăn trỏ tới /dish/{id}.", "mediaService.generateQR/generateDishQR ghép PUBLIC_BASE_URL (hoặc địa chỉ do quản trị viên nhập) với đường dẫn.", "Đã có"],
            ["BR-02", "Mã QR phải dùng địa chỉ truy cập được từ điện thoại, không dùng localhost.", "resolveQrBaseUrl loại localhost; giao diện cảnh báo và cho phép tạo lại với địa chỉ LAN.", "Đã có"],
            ["BR-03", "Mỗi địa điểm có tối đa một mã QR hiện hành.", "getQR lấy bản ghi theo culinary_place_id; generateQR cập nhật thay vì thêm mới.", "Đã có"],
            ["BR-04", "Một địa điểm có thể có nhiều bản dịch, mỗi ngôn ngữ tối đa một bản.", "UNIQUE (culinary_place_id, language_id) và upsert ON CONFLICT.", "Đã có"],
            ["BR-05", "Một bản dịch có tối đa một tệp âm thanh; tạo lại thì ghi đè.", "attachAudio tìm bản ghi cũ rồi UPDATE; dish_audio_guides có unique index theo translation_id.", "Đã có"],
            ["BR-06", "Nếu ngôn ngữ được chọn chưa có bản dịch, trang dùng bản dịch dự phòng thay vì hiển thị trống.", "placeService.getFullDetail chọn bản dịch đầu tiên có audio; trang địa điểm tự dò translations.", "Đã có"],
            ["BR-07", "Bản dịch phải có tên mới được lưu.", "upsertTranslation và upsertDishTranslation ném ApiError 400 nếu thiếu name.", "Đã có"],
            ["BR-08", "Chỉ ngôn ngữ chưa có nội dung mới được xoá; ngôn ngữ đang dùng phải tắt thay vì xoá.", "catalogService.deleteLanguage đếm bản dịch, trả 409 LANGUAGE_IN_USE.", "Đã có"],
            ["BR-09", "Chỉ địa điểm ở trạng thái PUBLISHED mới xuất hiện trong danh sách công khai; ARCHIVED trả 410.", "placeService.list lọc theo status; publicGuide kiểm tra ARCHIVED.", "Đã có"],
            ["BR-10", "Mỗi khách có đúng một ngôn ngữ miễn phí, áp dụng cho toàn phiên chứ không cấp lại theo từng QR.", "POST /api/guest-sessions/free-language kiểm tra bản ghi free trước khi ghi; ràng buộc UNIQUE (guest_session_id, language_id).", "Thiết kế / Một phần"],
            ["BR-11", "Ngôn ngữ bổ sung chỉ được mở sau khi thanh toán thành công và được xác minh ở máy chủ.", "Có bảng payment_transactions, audit và webhook; chưa có adapter xác thực chữ ký.", "Thiết kế"],
            ["BR-12", "Thao tác xác nhận thanh toán phải chịu được việc webhook bị gửi lặp.", "UNIQUE (provider, provider_event_id) và SELECT … FOR UPDATE trong guest.js.", "Một phần"],
            ["BR-13", "Không có giỏ hàng hoặc đặt món; thanh toán chỉ dùng để mở khoá ngôn ngữ.", "Không có bảng đơn hàng món ăn trong schema.", "Đã có"],
            ["BR-14", "Khách không cần đăng nhập để đọc nội dung công khai.", "Các tuyến /places, /dishes, /languages không dùng authenticate.", "Đã có"],
        ],
        "font": 10,
    }),

    ("h3", "1.2.4. Các ràng buộc của hệ thống"),
    ("b", [
        "Ràng buộc công nghệ: backend dùng CommonJS và Express 4 (không dùng TypeScript, không ORM); toàn bộ truy vấn viết bằng SQL thuần với tham số hoá.",
        "Ràng buộc dữ liệu: nội dung chỉ hiển thị khi có bản dịch tương ứng; ảnh và audio lưu trên đĩa, chỉ lưu đường dẫn trong cơ sở dữ liệu, nên phải mount volume khi chạy Docker.",
        "Ràng buộc trình duyệt: tính năng quét QR trên web cần getUserMedia và chỉ hoạt động trên HTTPS hoặc localhost; giọng đọc trình duyệt phụ thuộc danh sách voice đã cài trên thiết bị.",
        "Ràng buộc thiết bị di động: camera và GPS yêu cầu quyền của hệ điều hành; ứng dụng phải gọi được địa chỉ LAN của máy chủ, không dùng localhost.",
        "Ràng buộc mạng: trình phát audio tải tệp qua HTTP; nếu mạng chậm, người dùng phải chờ tệp hoặc dùng giọng trình duyệt.",
        "Ràng buộc dịch vụ ngoài: nhà cung cấp TTS có thể giới hạn tần suất hoặc thay đổi điều kiện sử dụng; Google Translate TTS không cần khoá nhưng không có cam kết ổn định.",
        "Ràng buộc pháp lý: nội dung thuyết minh do đơn vị quản lý chịu trách nhiệm; hệ thống không tự sinh ra dữ kiện lịch sử, văn hoá.",
    ]),

